import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 全册易错点 · 第27–53课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第一册：英语初阶 · 全册易错点 · 第27–53课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-1/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第1–26课","link":"/life/english/new-concept/book-1/mistakes-part-01"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第54–79课","link":"/life/english/new-concept/book-1/mistakes-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第1–26课","link":"/life/english/new-concept/book-1/mistakes-part-01"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第54–79课","link":"/life/english/new-concept/book-1/mistakes-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/mistakes-part-02.md","filePath":"life/english/new-concept/book-1/mistakes-part-02.md"}'),r={name:"life/english/new-concept/book-1/mistakes-part-02.md"};function i(s,e,l,p,h,c){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-全册易错点-·-第27–53课" tabindex="-1">第一册：英语初阶 · 全册易错点 · 第27–53课 <a class="header-anchor" href="#第一册-英语初阶-·-全册易错点-·-第27–53课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册易错点 · 第27–53课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="l27-·-there-are-与复数位置" tabindex="-1">L27 · there are 与复数位置 <a class="header-anchor" href="#l27-·-there-are-与复数位置" aria-label="Permalink to &quot;L27 · there are 与复数位置 {#l27-·-there-are-与复数位置}&quot;">​</a></h2><p>不要写 There is two lamps；复数灯需要 are。</p><p><strong>对照例句：</strong> There are two lamps beside the sofa.</p><p>There are 引出复数物品 two lamps；beside the sofa 是地点短语。are 与 lamps 的复数相配合。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-027">回看讲解和练习</a></p><h2 id="l28-·-there-are-与复数位置" tabindex="-1">L28 · there are 与复数位置 <a class="header-anchor" href="#l28-·-there-are-与复数位置" aria-label="Permalink to &quot;L28 · there are 与复数位置 {#l28-·-there-are-与复数位置}&quot;">​</a></h2><p>不要写 There is two lamps；复数灯需要 are。</p><p><strong>对照例句：</strong> The pictures are between the windows.</p><p>The pictures 是复数主语，所以用 are；between the windows 把多个窗户作为位置参照。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-028">回看讲解和练习</a></p><h2 id="l29-·-祈使句与-must" tabindex="-1">L29 · 祈使句与 must <a class="header-anchor" href="#l29-·-祈使句与-must" aria-label="Permalink to &quot;L29 · 祈使句与 must {#l29-·-祈使句与-must}&quot;">​</a></h2><p>must 后不用 to；must to tidy 应改为 must tidy。</p><p><strong>对照例句：</strong> Please close the cupboard quietly.</p><p>Please close 是礼貌指令，the cupboard 是 close 的宾语；quietly 是副词，修饰关柜子的动作。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-029">回看讲解和练习</a></p><h2 id="l30-·-祈使句与-must" tabindex="-1">L30 · 祈使句与 must <a class="header-anchor" href="#l30-·-祈使句与-must" aria-label="Permalink to &quot;L30 · 祈使句与 must {#l30-·-祈使句与-must}&quot;">​</a></h2><p>must 后不用 to；must to tidy 应改为 must tidy。</p><p><strong>对照例句：</strong> I must tidy my desk before lunch.</p><p>I 是主语，must 后直接接 tidy；my desk 是宾语，before lunch 说明完成动作的时间界限。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-030">回看讲解和练习</a></p><h2 id="l31-·-现在进行时单数" tabindex="-1">L31 · 现在进行时单数 <a class="header-anchor" href="#l31-·-现在进行时单数" aria-label="Permalink to &quot;L31 · 现在进行时单数 {#l31-·-现在进行时单数}&quot;">​</a></h2><p>Nora reading 缺少 is；问句也不能写 Does Nora is reading。</p><p><strong>对照例句：</strong> Nora is reading beside the window.</p><p>Nora 为单数主语，is reading 构成现在进行时；beside the window 只提供地点，不参与谓语变化。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-031">回看讲解和练习</a></p><h2 id="l32-·-现在进行时单数" tabindex="-1">L32 · 现在进行时单数 <a class="header-anchor" href="#l32-·-现在进行时单数" aria-label="Permalink to &quot;L32 · 现在进行时单数 {#l32-·-现在进行时单数}&quot;">​</a></h2><p>Nora reading 缺少 is；问句也不能写 Does Nora is reading。</p><p><strong>对照例句：</strong> Is the cat sleeping under the chair?</p><p>Is 从 is sleeping 中前置形成问句；the cat 是主语，under the chair 说明睡觉的位置。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-032">回看讲解和练习</a></p><h2 id="l33-·-现在进行时复数" tabindex="-1">L33 · 现在进行时复数 <a class="header-anchor" href="#l33-·-现在进行时复数" aria-label="Permalink to &quot;L33 · 现在进行时复数 {#l33-·-现在进行时复数}&quot;">​</a></h2><p>swim 的 ing 形式是 swimming；不要写 swiming。</p><p><strong>对照例句：</strong> The children are drawing by the pond.</p><p>The children 是复数主语，are drawing 表示现在正在进行的动作；by the pond 表在池塘旁边。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-033">回看讲解和练习</a></p><h2 id="l34-·-现在进行时复数" tabindex="-1">L34 · 现在进行时复数 <a class="header-anchor" href="#l34-·-现在进行时复数" aria-label="Permalink to &quot;L34 · 现在进行时复数 {#l34-·-现在进行时复数}&quot;">​</a></h2><p>swim 的 ing 形式是 swimming；不要写 swiming。</p><p><strong>对照例句：</strong> Two dogs are running across the field.</p><p>Two dogs 是复数主语；run 双写 n 后加 ing，are running 构成进行时；across the field 表横穿田野。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-034">回看讲解和练习</a></p><h2 id="l35-·-位置与方向介词" tabindex="-1">L35 · 位置与方向介词 <a class="header-anchor" href="#l35-·-位置与方向介词" aria-label="Permalink to &quot;L35 · 位置与方向介词 {#l35-·-位置与方向介词}&quot;">​</a></h2><p>across 强调横穿，along 强调沿线行进；方向不同不能互换。</p><p><strong>对照例句：</strong> A narrow bridge crosses the river.</p><p>A narrow bridge 是单数主语，crosses 是一般现在时第三人称形式；the river 是 crosses 的宾语。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-035">回看讲解和练习</a></p><h2 id="l36-·-位置与方向介词" tabindex="-1">L36 · 位置与方向介词 <a class="header-anchor" href="#l36-·-位置与方向介词" aria-label="Permalink to &quot;L36 · 位置与方向介词 {#l36-·-位置与方向介词}&quot;">​</a></h2><p>across 强调横穿，along 强调沿线行进；方向不同不能互换。</p><p><strong>对照例句：</strong> The visitors are walking along the river.</p><p>The visitors 为复数主语，are walking 描述正在步行；along the river 说明沿河线性移动，而不是横渡河流。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-036">回看讲解和练习</a></p><h2 id="l37-·-be-going-to-表计划" tabindex="-1">L37 · be going to 表计划 <a class="header-anchor" href="#l37-·-be-going-to-表计划" aria-label="Permalink to &quot;L37 · be going to 表计划 {#l37-·-be-going-to-表计划}&quot;">​</a></h2><p>going to 后接原形，不能写 going to painting。</p><p><strong>对照例句：</strong> We are going to paint the bench tomorrow.</p><p>We are going to paint 表计划，paint 用原形；the bench 为宾语，tomorrow 把计划放在明天。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-037">回看讲解和练习</a></p><h2 id="l38-·-be-going-to-表计划" tabindex="-1">L38 · be going to 表计划 <a class="header-anchor" href="#l38-·-be-going-to-表计划" aria-label="Permalink to &quot;L38 · be going to 表计划 {#l38-·-be-going-to-表计划}&quot;">​</a></h2><p>going to 后接原形，不能写 going to painting。</p><p><strong>对照例句：</strong> I am measuring the shelf now.</p><p>I am measuring 是现在进行时，now 强调眼前动作；它与计划结构 going to measure 的时间视角不同。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-038">回看讲解和练习</a></p><h2 id="l39-·-否定祈使句与宾语代词" tabindex="-1">L39 · 否定祈使句与宾语代词 <a class="header-anchor" href="#l39-·-否定祈使句与宾语代词" aria-label="Permalink to &quot;L39 · 否定祈使句与宾语代词 {#l39-·-否定祈使句与宾语代词}&quot;">​</a></h2><p>否定指令用 Don&#39;t put，不用 Not put；carry 后的 it 是宾语。</p><p><strong>对照例句：</strong> Do not put the wet box on the bed.</p><p>Do not 加 put 原形构成否定祈使句；the wet box 为对象，on the bed 为禁止放置的位置。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-039">回看讲解和练习</a></p><h2 id="l40-·-否定祈使句与宾语代词" tabindex="-1">L40 · 否定祈使句与宾语代词 <a class="header-anchor" href="#l40-·-否定祈使句与宾语代词" aria-label="Permalink to &quot;L40 · 否定祈使句与宾语代词 {#l40-·-否定祈使句与宾语代词}&quot;">​</a></h2><p>否定指令用 Don&#39;t put，不用 Not put；carry 后的 it 是宾语。</p><p><strong>对照例句：</strong> We are going to carry it upstairs.</p><p>We are going to carry 表打算；it 指前文物品，作 carry 的宾语；upstairs 是方向副词，不加 to。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-040">回看讲解和练习</a></p><h2 id="l41-·-不可数名词与量词" tabindex="-1">L41 · 不可数名词与量词 <a class="header-anchor" href="#l41-·-不可数名词与量词" aria-label="Permalink to &quot;L41 · 不可数名词与量词 {#l41-·-不可数名词与量词}&quot;">​</a></h2><p>普通物质义的 paper 不写 a paper；一张纸用 a sheet/piece of paper。</p><p><strong>对照例句：</strong> There is a bottle of juice in my bag.</p><p>There is 的单数依据是数量核心 a bottle；of juice 说明瓶中内容，in my bag 是地点。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-041">回看讲解和练习</a></p><h2 id="l42-·-不可数名词与量词" tabindex="-1">L42 · 不可数名词与量词 <a class="header-anchor" href="#l42-·-不可数名词与量词" aria-label="Permalink to &quot;L42 · 不可数名词与量词 {#l42-·-不可数名词与量词}&quot;">​</a></h2><p>普通物质义的 paper 不写 a paper；一张纸用 a sheet/piece of paper。</p><p><strong>对照例句：</strong> Is there any paper in the drawer?</p><p>Is there 询问存在，paper 为物质义不可数名词，any 表不确定数量；in the drawer 说明搜索范围。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-042">回看讲解和练习</a></p><h2 id="l43-·-some-any-与存在句疑问" tabindex="-1">L43 · some/any 与存在句疑问 <a class="header-anchor" href="#l43-·-some-any-与存在句疑问" aria-label="Permalink to &quot;L43 · some/any 与存在句疑问 {#l43-·-some-any-与存在句疑问}&quot;">​</a></h2><p>回答 Are there ...? 要用 Yes, there are；不要写 Yes, they are。</p><p><strong>对照例句：</strong> Are there any clean mugs in the cupboard?</p><p>Mugs 为复数，所以用 Are there；any 在中性疑问中表示有没有一些，clean 修饰 mugs。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-043">回看讲解和练习</a></p><h2 id="l44-·-some-any-与存在句疑问" tabindex="-1">L44 · some/any 与存在句疑问 <a class="header-anchor" href="#l44-·-some-any-与存在句疑问" aria-label="Permalink to &quot;L44 · some/any 与存在句疑问 {#l44-·-some-any-与存在句疑问}&quot;">​</a></h2><p>回答 Are there ...? 要用 Yes, there are；不要写 Yes, they are。</p><p><strong>对照例句：</strong> There is not any milk in the fridge.</p><p>Milk 为不可数名词，所以用 is；not any 表数量为零。in the fridge 限定不存在牛奶的位置。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-044">回看讲解和练习</a></p><h2 id="l45-·-can-表能力" tabindex="-1">L45 · can 表能力 <a class="header-anchor" href="#l45-·-can-表能力" aria-label="Permalink to &quot;L45 · can 表能力 {#l45-·-can-表能力}&quot;">​</a></h2><p>can 后不能加 to，也不能用第三人称形式 translates。</p><p><strong>对照例句：</strong> My colleague can translate this message.</p><p>My colleague 是第三人称单数，但 can 不加 s；translate 用原形，this message 为宾语。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-045">回看讲解和练习</a></p><h2 id="l46-·-can-表能力" tabindex="-1">L46 · can 表能力 <a class="header-anchor" href="#l46-·-can-表能力" aria-label="Permalink to &quot;L46 · can 表能力 {#l46-·-can-表能力}&quot;">​</a></h2><p>can 后不能加 to，也不能用第三人称形式 translates。</p><p><strong>对照例句：</strong> Can you print the report today?</p><p>Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-046">回看讲解和练习</a></p><h2 id="l47-·-实义动词的一般现在时问句" tabindex="-1">L47 · 实义动词的一般现在时问句 <a class="header-anchor" href="#l47-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;L47 · 实义动词的一般现在时问句 {#l47-·-实义动词的一般现在时问句}&quot;">​</a></h2><p>不要把 Do you like 写成 Are you like；这里 like 是动词。</p><p><strong>对照例句：</strong> Do you like coffee without sugar?</p><p>Do 帮助 like 形成一般疑问句；coffee 是宾语，without sugar 修饰所说的咖啡，表示不加糖。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-047">回看讲解和练习</a></p><h2 id="l48-·-实义动词的一般现在时问句" tabindex="-1">L48 · 实义动词的一般现在时问句 <a class="header-anchor" href="#l48-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;L48 · 实义动词的一般现在时问句 {#l48-·-实义动词的一般现在时问句}&quot;">​</a></h2><p>不要把 Do you like 写成 Are you like；这里 like 是动词。</p><p><strong>对照例句：</strong> I do not want a cold drink now.</p><p>I do not want 是一般现在时否定；want 保持原形，a cold drink 为宾语，now 说明当前需求。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-048">回看讲解和练习</a></p><h2 id="l49-·-第三人称单数与-does" tabindex="-1">L49 · 第三人称单数与 does <a class="header-anchor" href="#l49-·-第三人称单数与-does" aria-label="Permalink to &quot;L49 · 第三人称单数与 does {#l49-·-第三人称单数与-does}&quot;">​</a></h2><p>Does she eats? 中 eats 应改为 eat；第三人称变化只保留在 does。</p><p><strong>对照例句：</strong> My brother prefers fish to beef.</p><p>My brother 是单数主语，prefer 加 s；prefer A to B 表示在两者之间偏爱 A，to 不是不定式标记。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-049">回看讲解和练习</a></p><h2 id="l50-·-第三人称单数与-does" tabindex="-1">L50 · 第三人称单数与 does <a class="header-anchor" href="#l50-·-第三人称单数与-does" aria-label="Permalink to &quot;L50 · 第三人称单数与 does {#l50-·-第三人称单数与-does}&quot;">​</a></h2><p>Does she eats? 中 eats 应改为 eat；第三人称变化只保留在 does。</p><p><strong>对照例句：</strong> Does your daughter eat carrots?</p><p>Does 标记第三人称疑问，your daughter 为主语，eat 恢复原形；carrots 作泛指食物，不加冠词。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-050">回看讲解和练习</a></p><h2 id="l51-·-come-from-与国籍表达" tabindex="-1">L51 · come from 与国籍表达 <a class="header-anchor" href="#l51-·-come-from-与国籍表达" aria-label="Permalink to &quot;L51 · come from 与国籍表达 {#l51-·-come-from-与国籍表达}&quot;">​</a></h2><p>天气形容词前用 be；It windy 缺谓语，It is rains 又混合两种结构。</p><p><strong>对照例句：</strong> My neighbours come from Portugal.</p><p>My neighbours 是复数主语，come 不加 s；from Portugal 是来源信息，不能把 come 换成 are come。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-051">回看讲解和练习</a></p><h2 id="l52-·-come-from-与国籍表达" tabindex="-1">L52 · come from 与国籍表达 <a class="header-anchor" href="#l52-·-come-from-与国籍表达" aria-label="Permalink to &quot;L52 · come from 与国籍表达 {#l52-·-come-from-与国籍表达}&quot;">​</a></h2><p>天气形容词前用 be；It windy 缺谓语，It is rains 又混合两种结构。</p><p><strong>对照例句：</strong> It is often windy here in spring.</p><p>It 是天气主语；is 后放频率副词 often，windy 为表语。in spring 说明季节，不用 on。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-052">回看讲解和练习</a></p><h2 id="l53-·-频率副词与天气动词" tabindex="-1">L53 · 频率副词与天气动词 <a class="header-anchor" href="#l53-·-频率副词与天气动词" aria-label="Permalink to &quot;L53 · 频率副词与天气动词 {#l53-·-频率副词与天气动词}&quot;">​</a></h2><p>often 在 be 后、普通动词前是常见位置；不要机械认为所有副词都放句尾。</p><p><strong>对照例句：</strong> It often rains in this coastal town.</p><p>It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。</p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-053">回看讲解和练习</a></p>',138)])])}const u=a(r,[["render",i]]);export{d as __pageData,u as default};
